54	/**
55	 * Converts OpenAI tool format to Vercel AI SDK format.
56	 *
57	 * OpenAI format: { type: "function", function: { name, description, parameters: JSONSchema } }
58	 * Vercel format: { [toolName]: { description, parameters: aiJsonSchema(JSONSchema) } }
59	 *
60	 * @param openaiTools - Array of OpenAI tools or undefined
61	 * @returns Object with tool names as keys, or undefined if no tools
62	 */
63	export async function convertToolsToVercelFormat(
64	  openaiTools?: ChatCompletionCreateParams["tools"],
65	): Promise<Record<string, any> | undefined> {
66	  if (!openaiTools || openaiTools.length === 0) {
67	    return undefined;
68	  }
69	
70	  const { jsonSchema: aiJsonSchema } = await import("ai");
71	
72	  const vercelTools: Record<string, any> = {};
73	  for (const tool of openaiTools) {
74	    if (tool.type === "function") {
75	      const parameters = makeOpenAIStrictCompatible(
76	        tool.function.parameters ?? { type: "object", properties: {} },
77	      );
78	      vercelTools[tool.function.name] = {
79	        description: tool.function.description,
80	        parameters: aiJsonSchema(parameters),
81	      };
82	    }
83	  }
84	
85	  return Object.keys(vercelTools).length > 0 ? vercelTools : undefined;
86	}
